// ============================================================
// Validar Payload
// ------------------------------------------------------------
// Mismo contrato que v1: { playlistId, userId, prompt, size,
// genres, mood, language, catalogSample, callbackUrl, callbackSecret }
// ============================================================

const payload = $json.body;
if (!payload) throw new Error('Request body is missing');

const { playlistId, userId, prompt, size, genres, mood, language,
  catalogSample, callbackUrl, callbackSecret } = payload;

if (!Number.isInteger(playlistId) || playlistId <= 0)
  throw new Error(`playlistId inválido: ${playlistId}`);
if (!Number.isInteger(userId) || userId <= 0)
  throw new Error(`userId inválido: ${userId}`);
if (!prompt || typeof prompt !== 'string' || prompt.length < 5)
  throw new Error('prompt vacío o demasiado corto');
if (!callbackUrl || typeof callbackUrl !== 'string' || !/^https?:\/\//.test(callbackUrl))
  throw new Error(`callbackUrl inválido: ${callbackUrl}`);
if (!Array.isArray(catalogSample) || catalogSample.length === 0)
  throw new Error('catalogSample vacío');

const safeSample = catalogSample
  .filter(b => Number.isInteger(b?.id) && typeof b?.title === 'string')
  .slice(0, 80);

const allowedIds = safeSample.map(b => b.id);
const targetSize = Number.isInteger(size) ? Math.max(3, Math.min(25, size)) : 8;

// Construir el input del agente
const sampleList = safeSample
  .map(b => `- [${b.id}] ${b.title}${b.author ? ' — ' + b.author : ''}`)
  .join('\n');

const genreStr = Array.isArray(genres) && genres.length > 0 ? genres.slice(0, 10).join(', ') : 'no especificados';
const moodStr = typeof mood === 'string' && mood ? mood.slice(0, 80) : 'no especificado';
const lang = typeof language === 'string' ? language.slice(0, 20) : 'es';

const agentInput = `Genera una playlist de lectura coherente y atractiva.

PETICIÓN DEL USUARIO:
"${prompt.trim()}"

Géneros preferidos: ${genreStr}
Estado de ánimo / vibra: ${moodStr}
Tamaño deseado: ${targetSize} libros
Idioma de respuesta: ${lang}

CATÁLOGO EXISTENTE (IDs ya confirmados — úsalos si encajan):
${sampleList}

playlistId: ${playlistId}`;

return {
  playlistId, userId, prompt: prompt.trim(),
  size: targetSize,
  genres: Array.isArray(genres) ? genres.slice(0, 10) : [],
  mood: moodStr,
  language: lang,
  catalogSample: safeSample,
  allowedIds,
  callbackUrl,
  callbackSecret: callbackSecret || null,
  agentInput,
  startTime: Date.now()
};

// ============================================================
// Parsear Respuesta del AI Agent
// ------------------------------------------------------------
// Extrae el JSON del agente, valida catalogBookIds contra allowedIds
// (IDs del catalogSample original + IDs recién insertados que el
// backend ya tendrá cuando llegue el callback).
// ============================================================

const prev = $('Validar Payload').item.json;
const agentOutput = $input.item.json.output || '';

let parsed = null;
try {
  let clean = agentOutput.trim();
  if (clean.startsWith('```')) {
    clean = clean.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
  }
  parsed = JSON.parse(clean);
} catch (err) {
  return {
    ...prev,
    aiStatus: 'error',
    aiErrorMessage: 'Respuesta del agente no es JSON válido: ' + (err?.message || err),
    aiTitle: null,
    aiDescription: null,
    aiCoverUrl: null,
    aiItems: []
  };
}

if (!parsed || parsed.status === 'error') {
  return {
    ...prev,
    aiStatus: 'error',
    aiErrorMessage: parsed?.errorMessage || 'El agente indicó status:error',
    aiTitle: null,
    aiDescription: null,
    aiCoverUrl: null,
    aiItems: []
  };
}

// Validar items: solo IDs que existan (el agente puede haber insertado nuevos
// en add_books_to_catalog, esos IDs son válidos aunque no estén en allowedIds original)
const rawItems = Array.isArray(parsed.items) ? parsed.items : [];
const cleanItems = [];
const seen = new Set();

for (const it of rawItems) {
  const id = Number(it?.catalogBookId);
  if (!Number.isInteger(id) || id <= 0 || seen.has(id)) continue;
  seen.add(id);
  cleanItems.push({
    catalogBookId: id,
    position: cleanItems.length + 1,
    note: typeof it?.note === 'string' ? it.note.slice(0, 500) : null
  });
  if (cleanItems.length >= prev.size) break;
}

if (cleanItems.length === 0) {
  return {
    ...prev,
    aiStatus: 'error',
    aiErrorMessage: 'El agente no devolvió items válidos',
    aiTitle: null,
    aiDescription: null,
    aiCoverUrl: null,
    aiItems: []
  };
}

const aiTitle = typeof parsed.title === 'string' ? parsed.title.slice(0, 100) : null;
const aiDescription = typeof parsed.description === 'string' ? parsed.description.slice(0, 2000) : null;

return {
  ...prev,
  aiStatus: 'success',
  aiErrorMessage: null,
  aiTitle,
  aiDescription,
  aiItems: cleanItems,
  processingTime: Date.now() - (prev.startTime || Date.now())
};

// Genera la portada de la playlist con Pollinations (1024x1024)
// Solo para la portada del AGREGADO (no de los libros individuales, esos tienen portadas reales)
const data = $input.item.json;

const coverPromptParts = [
  'book collection cover art',
  data.aiTitle || data.prompt.slice(0, 80),
  Array.isArray(data.genres) && data.genres.length > 0 ? data.genres.slice(0, 3).join(' ') : '',
  data.mood && data.mood !== 'no especificado' ? data.mood : '',
  'stylized vibrant painterly minimalist no text no letters'
].filter(Boolean);

const coverPrompt = coverPromptParts.join(', ').slice(0, 300);
const encoded = encodeURIComponent(coverPrompt);
// Resolución mejorada a 1024x1024 para mayor calidad visual
const aiCoverUrl = `https://image.pollinations.ai/prompt/${encoded}?width=1024&height=1024&nologo=true&model=flux&seed=${data.playlistId}`;

return { ...data, aiCoverUrl };

